insert into technique_lessons(id,title,technique_type,explanation_text,order_index) values (1,'Give memories a hook','Peg system','Learn a fixed list of familiar pegs, then hang new information on them. For a rhyme list, one is a bun, two is a shoe, three is a tree. To remember lemons first, imagine a bun bursting with bright yellow lemons.',0) on conflict(id) do nothing;
insert into technique_lessons(id,title,technique_type,explanation_text,order_index) values (2,'Turn numbers into pictures','Phonetic peg','In the major system, consonant sounds encode digits: 0 s/z, 1 t/d, 2 n, 3 m, 4 r, 5 l, 6 sh/ch/j, 7 k/g, 8 f/v, 9 p/b. Vowels help form words. 12 can become “tin”: t = 1, n = 2. Picture a huge tin to remember that pair.',1) on conflict(id) do nothing;
insert into technique_lessons(id,title,technique_type,explanation_text,order_index) values (3,'Link a tiny, strange story','Chain method','Connect each item to the next through an exaggerated action. The end of one picture becomes the beginning of another. A lemon rolls into a shoe. The shoe kicks a kite. The kite lifts a book.',2) on conflict(id) do nothing;
insert into technique_lessons(id,title,technique_type,explanation_text,order_index) values (4,'Let the initials guide you','Acrostic method','Take the first letter of each item and make a memorable sentence. Keep the order consistent and practice recovering the original items. For North, East, South, West: “New Explorers Seek Wonders.”',3) on conflict(id) do nothing;
insert into technique_lessons(id,title,technique_type,explanation_text,order_index) values (5,'Make a name memorable','Personal Nick Name','Privately connect a new name with a vivid, friendly image. Use a sound association that makes sense to you, then link it to the person. For someone named Rose, imagine them holding an enormous rose. Recall the image when you meet again.',4) on conflict(id) do nothing;
insert into technique_lessons(id,title,technique_type,explanation_text,order_index) values (6,'Take a walk through memory','Method of loci','Choose a familiar route and fixed locations along it. Place one vivid image at each stop. Mentally walk the same route to retrieve the information. At the market: lantern → watch → butterfly → sapling → chest → signpost.',5) on conflict(id) do nothing;
